<script setup>
import { formatSize } from '@/utils/util'
import useChatStore from '@/stores/chat'
import useKnowledgeStore from '@/stores/knowledge'
import { createKnowledge, getEmbedModels, getDocChatEmbedModel } from '@/services/knowledge'
import FileHistory from './FileHistory.vue'
import DocChatConfig from './DocChatConfig.vue'
import { getFileType, fileIconRender } from '@/views/knowledge/FileIcon'
import Markdown from '@/views/chat/components/Markdown.vue'

const fileList = ref([])
const fileId = ref('')

const uploaderRef = ref()

const chatStore = useChatStore()
const kbStore = useKnowledgeStore()

const loading = ref(false)
const fileUploader = (event) => {
  const formData = new FormData()
  formData.append('id', chatStore.currentConversationId)
  formData.append('name', chatStore.currentConversationId)
  formData.append(
    'knowledge_setting',
    JSON.stringify({
      embed_model: embed_model.value
    })
  )
  if (event.files.length > 0) {
    event.files.forEach((file) => {
      formData.append('files', file)
    })
  } else {
    formData.append('files', new File([], ''))
  }

  loading.value = true
  fileList.value = []
  createKnowledge(formData)
    .then((res) => {
      const result = res.resData
      fileId.value = result[0]
      fileList.value = event.files
      if (fileList.value.length > 0) {
        const fileName = fileList.value[0].name
        const fileType = getFileType(fileName)
        kbStore.setFileInfo({
          id: fileId.value,
          name: fileName,
          type: fileType
        })
      }
      uploaderRef.value.clear()
      uploaderRef.value.uploadedFileCount = 0
      getModelList()
    })
    .finally(() => {
      loading.value = false
    })
}

function viewFile() {
  const fileName = fileList.value[0].name
  const fileType = getFileType(fileName)
  const fileTypeList = ['txt', 'html', 'htm', 'md', 'json', 'jsonl', 'xml', 'pdf', 'docx'] //  'epub', 'mobi', 'pptx'
  if (fileTypeList.includes(fileType)) {
    kbStore.setFileView(true)
    kbStore.setFileInfo({
      id: fileId.value,
      name: fileList.value[0].name,
      type: fileType
    })
  }
}

function onFileSelect() {
  removeFile()
}

function removeFile() {
  fileList.value = []
  fileId.value = []
  kbStore.setFileView(false)
  kbStore.setFileInfo({})
}

const dialogVisible = ref(false)

function handleSelectFile(data) {
  fileId.value = data.id
  fileList.value = [
    {
      id: data.id,
      name: data.name,
      size: data.bytetotal
    }
  ]

  kbStore.setFileInfo({
    id: fileId.value,
    name: data.name,
    type: getFileType(data.name)
  })

  resetDialog()
}

const fileHistoryFlag = ref(false)
const docChatConfigFlag = ref(false)

function showFileHistory() {
  dialogVisible.value = true
  nextTick(() => {
    fileHistoryFlag.value = true
  })
}

function openDocSetting() {
  dialogVisible.value = true
  nextTick(() => {
    docChatConfigFlag.value = true
  })
}

function resetDialog() {
  dialogVisible.value = false
  fileHistoryFlag.value = false
  docChatConfigFlag.value = false
}

function iconRender(fileName) {
  const type = getFileType(fileName)
  return fileIconRender(type)
}

const showhasnoflag = ref(false)

const needaddembed = `
请前往 ⚙️<strong>【设置】</strong>-<strong>【嵌入模型】</strong> 中，进行模型选择与设置
`

const embed_model = ref('')
const is_editable = ref(true)
const modelList = ref([])
async function getModelList() {
  try {
    const res = await getEmbedModels()
    const result = res.resData
    modelList.value = result.filter((item) => item.key === 'ollama' || item.key === 'siliconflow')

    if (modelList.value.length === 0) {
      showhasnoflag.value = true
    } else {
      const docRes = await getDocChatEmbedModel(chatStore.currentConversationId)
      embed_model.value = docRes.resData.local_path
      is_editable.value = docRes.resData.is_editable
    }
  } catch (error) {
    console.error('获取模型失败:', error)
    showhasnoflag.value = true
  }
}

onMounted(() => {
  getModelList().then(() => {
    if (modelList.value.length > 0) {
      fileUploader({ files: [] })
    }
  })
})

const formatOptionLabel = (option) => {
  if (!option) return ''
  return `${option.cn_name} : ${option.name}`
}

onUnmounted(() => {
  kbStore.clearPluginData()
})
</script>
<template>
  <div>
    <!-- <div class="file-container w-full flex flex-col justify-start items-start tabs-item"> -->
    <div
      class="file-container relative flex flex-col items-start justify-start w-[280px] -left-[28px] top-[50px] cursor-pointer overflow-hidden"
    >
      <div class="flex justify-start items-center">
        <label class="text-slate-500 font-bold text-sm">{{ $t('kb.embedModelPath') }}</label>
        <Dropdown
          class="w-[200px] ml-2"
          v-model="embed_model"
          :options="modelList"
          :optionLabel="formatOptionLabel"
          optionValue="local_path"
          :disabled="!is_editable"
        />
      </div>
      <Dialog v-model:visible="showhasnoflag" header="未检测到可使用的【嵌入模型】" :style="{ width: '800px' }" :modal="true">
        <div class="content-box">
          <Markdown :content="needaddembed"></Markdown>
        </div>
      </Dialog>
      <div class="flex mt-2">
        <FileUpload
          mode="basic"
          name="uploader"
          ref="uploaderRef"
          url=""
          accept=".pdf,.docx,.txt,.html,.htm,.md,.json,.jsonl,.epub,.mobi,.xml,.pptx"
          :choose-label="$t('kb.selectFile')"
          upload-icon="pi pi-file"
          :maxFileSize="500 * 1024 * 1024"
          auto
          customUpload
          @uploader="fileUploader"
          @select="onFileSelect"
          :disabled="loading"
          :pt="{
            chooseButton: {
              class: 'p-button-text'
            }
          }"
        >
          <template #uploadicon>
            <i class="pi pi-spin pi-spinner mr-1" v-if="loading"></i>
            <i class="pi pi-file mr-1" v-else></i>
          </template>
        </FileUpload>
        <div>
          <Button icon="pi pi-clock" text :label="$t('kb.fileHistory')" @click="showFileHistory"></Button>
          <Button text @click="openDocSetting" :label="$t('lang.config')" />
        </div>
      </div>
      <div class="flex items-center w-full mt-2 cursor-pointer" v-if="fileList.length > 0">
        <!-- <i class="pi pi-file-pdf text-4xl"></i> -->
        <img :src="iconRender(fileList[0].name)" alt="" style="width: 35px; margin-right: 5px" />
        <div @click="viewFile">
          <div class="w-52 break-all whitespace-nowrap overflow-hidden text-ellipsis">{{ fileList[0].name }}</div>
          <div>{{ formatSize(fileList[0].size) }}</div>
        </div>
        <div class="ml-4">
          <Button icon="pi pi-times" @click="removeFile()" rounded text severity="danger" />
        </div>
      </div>
    </div>
    <Dialog
      v-model:visible="dialogVisible"
      modal
      :header="fileHistoryFlag ? $t('kb.fileHistory') : $t('lang.config')"
      class="w-2/5 min-w-[600px]"
      @hide="resetDialog"
    >
      <FileHistory ref="fileHistoryRef" v-if="fileHistoryFlag" @selectFile="handleSelectFile" @hide="resetDialog" />
      <DocChatConfig
        ref="docChatConfigRef"
        v-if="docChatConfigFlag"
        :kbId="chatStore.currentConversationId"
        :sessionId="chatStore.currentConversationId"
        type="chat_files_retrievers"
        @success="resetDialog"
        @hide="resetDialog"
      />
    </Dialog>
  </div>
</template>

<style scoped lang="scss"></style>
